// ---------------------------------------------------------------------------
// Chats (Phase 2). Every `*_url` below that starts with `/media/` is relative to the module base and
// already signed; the client puts the base in front and uses it as an <img>/<audio>/<video> source.
// ---------------------------------------------------------------------------

export type MessageKind = 'text' | 'audio' | 'image' | 'video' | 'document' | 'sticker' | 'other';
export type MessageDirection = 'in' | 'out';

export interface ChatListItem {
  id: string;
  title: string;
  is_group: boolean;
  /** The WAAI user who owns the chat; shown to admins, who see everyone's chats. */
  owner_email: string;
  avatar_url: string | null;
  /** Unread incoming messages, mirrored from WhatsApp. */
  unread_count: number;
  /** ISO timestamp. */
  last_message_at: string;
  last_message: {
    kind: MessageKind;
    body: string | null;
    sender: string | null;
    direction: MessageDirection;
  } | null;
}

/** One line of a chat's AI summary: narrative context, or the report of one extracted task. */
export interface ChatSummaryBullet {
  text: string;
  /** Set when the line reports a task; the line retires when that task is completed. */
  task_id: string | null;
}

/** The cached "recent" summary shown under a chat row. */
export interface ChatSummaryPreview {
  action_items: ChatSummaryBullet[];
  narrative: string;
  message_count: number;
  /** ISO timestamp. */
  created_at: string;
}

/** `GET /conversations` (optionally `?owner=<userId>`, admins only). */
export interface ConversationsResponse {
  conversations: ChatListItem[];
  /** Keyed by conversation id; a chat without a fresh summary has no entry. */
  summaries: Record<string, ChatSummaryPreview>;
  /** Of the tasks the summaries report, the ones already ticked off. */
  completed_task_ids: string[];
  /** The text AI has a key. Only meaningful for the caller's own list. */
  ai_configured: boolean;
  /** At least one WhatsApp account completed pairing. Only meaningful for the caller's own list. */
  has_wa_account: boolean;
  /** Whose list this is, as the header names them. */
  user_name: string;
  user_avatar_url: string | null;
}

