// ---------------------------------------------------------------------------
// Phase 3: Chats, write. Sending, attachments, voice notes, reactions, edit, delete, forward, AI text
// assist, open by phone. Everything a write endpoint refuses with carries a stable reason in the error
// envelope's `message` (see `WriteFailureReason`).
// ---------------------------------------------------------------------------

export const PHASE3_FEATURES = ['send', 'message_ops', 'text_assist', 'open_by_phone'] as const;
export type Phase3Feature = (typeof PHASE3_FEATURES)[number];

/** The largest attachment WAAI accepts, in bytes. */
export const MAX_SEND_FILE_BYTES = 32 * 1024 * 1024;
/** The longest message text; WhatsApp's own limit. */
export const MAX_MESSAGE_CHARS = 65_536;
/** WhatsApp lets a message be edited for 15 minutes after it was sent. */
export const EDIT_WINDOW_MS = 15 * 60 * 1000;

/**
 * Why a write was refused: the error envelope's `message` for these endpoints. The envelope's `code` is
 * the HTTP class (`offline` and `conflict` 409, `payload_too_large` 413, `invalid_input` 400/422,
 * `not_found` 404, `server_error` 5xx, `not_implemented` 501); the reason says which one.
 */
export type WriteFailureReason =
  | 'offline' // the WhatsApp account is not connected right now
  | 'empty'
  | 'too_long'
  | 'too_large'
  | 'send_failed'
  | 'timeout'
  | 'not_revocable'
  | 'not_editable'
  | 'edit_window_expired'
  | 'empty_body'
  | 'edit_failed'
  | 'delete_failed'
  | 'invalid_emoji'
  | 'unsupported'
  | 'react_failed'
  | 'missing_target'
  | 'target_not_found'
  | 'cross_account'
  | 'forward_failed'
  | 'ai_unconfigured'
  | 'assist_failed'
  | 'invalid_action'
  | 'missing_target_lang';

/**
 * `POST /conversations/:id/send`, as JSON. The same message with an attachment goes as
 * `multipart/form-data` with the fields `text`, `draft_text`, `quoted_message_id`, `as_voice` ("1" for a
 * voice note) and `file`.
 */
export interface SendMessageRequest {
  /** The text, or the caption of the attachment. Empty only when there is an attachment. */
  text: string;
  /** The in-app id of the message this one replies to; it must be in the same chat. */
  quoted_message_id?: string | null;
  /** What was typed before it was translated for sending; shown under the bubble as the original. */
  draft_text?: string | null;
}

export interface SendMessageResponse {
  /** The message as it is stored, in the shape `GET …/messages` serves it. */
  message: MessageDto;
}

/** `PATCH /messages/:id` */
export interface EditMessageRequest {
  body: string;
  /** The untranslated draft, kept as the bubble's note. */
  draft_text?: string;
}

export interface EditMessageResponse {
  id: string;
  body: string;
  edited_at: string;
  translation_note: string | null;
}

/** `DELETE /messages/:id?scope=me|everyone`: `me` hides it in the app, `everyone` revokes it on WhatsApp (own messages only). */
export type DeleteMessageScope = 'me' | 'everyone';

export interface OkResponse {
  ok: true;
}

/** `POST /messages/:id/reaction`; `emoji: null` removes the user's reaction. */
export interface ReactionRequest {
  emoji: string | null;
}

/** The message's reactions as they now stand. */
export interface ReactionResponse {
  reactions: ReactionGroup[];
}

/** `POST /messages/:id/forward`; the target must be a chat of the same WhatsApp account. */
export interface ForwardMessageRequest {
  target_conversation_id: string;
}

export interface ForwardTarget {
  id: string;
  title: string;
  is_group: boolean;
  avatar_url: string | null;
  /** Forwarding works only within one account: the picker greys out the others. */
  wa_account_id: string;
}

/** `GET /conversations/lite`: up to 200 chats, newest first. */
export interface ForwardTargetsResponse {
  conversations: ForwardTarget[];
}

export type AssistLanguage = 'en' | 'sk' | 'hu';

/** `POST /chat/text-assist` */
export interface TextAssistRequest {
  text: string;
  action: 'translate' | 'fix';
  /** The language to translate into, or to write the fixed text in (default: detected). */
  target_lang?: AssistLanguage;
  source_lang?: AssistLanguage;
}

export interface TextAssistResponse {
  text: string;
  lang: AssistLanguage;
  source_lang: AssistLanguage | null;
  /** The text was already in the target language; `text` is the input. */
  skipped: boolean;
}

/** `POST /open/check` */
export interface OpenCheckRequest {
  /** Digits only, with the country code. */
  phone: string;
}

export type OpenFailureCode = 'offline' | 'unsupported' | 'limit' | 'failed';

export type OpenCheckResponse =
  | { status: 'registered' }
  | { status: 'not_registered' }
  | { status: 'error'; code: OpenFailureCode };

/** `POST /open/start`: sends the first message and pins the chat to the CRM record that asked for it. */
export interface OpenStartRequest {
  phone: string;
  text: string;
  lead_id?: string | null;
  project_id?: string | null;
}

export type OpenStartResponse =
  /** `conversation_id` is null when the chat has not shown up yet; the list will have it shortly. */
  | { ok: true; conversation_id: string | null }
  | { ok: false; code: 'offline' | 'not_registered' | 'limit' | 'failed' | 'invalid' };
